-- Forward reconciliation of the hierarchy fields consumed by the existing
-- public API. Existing identifiers and ward links retain their original values.
BEGIN;

ALTER TABLE public.urban_local_bodies ADD COLUMN IF NOT EXISTS internal_id uuid;
ALTER TABLE public.gram_panchayats ADD COLUMN IF NOT EXISTS internal_id uuid;
ALTER TABLE public.ulb_wards ADD COLUMN IF NOT EXISTS internal_id uuid;
ALTER TABLE public.gp_wards ADD COLUMN IF NOT EXISTS internal_id uuid;
ALTER TABLE public.polling_booths
  ADD COLUMN IF NOT EXISTS internal_id uuid,
  ADD COLUMN IF NOT EXISTS ulb_ward_internal_id uuid,
  ADD COLUMN IF NOT EXISTS gp_ward_internal_id uuid,
  ADD COLUMN IF NOT EXISTS data_status public.data_status_enum NOT NULL DEFAULT 'UNVERIFIED';

