  SET registered_voters = report.electors,
      total_voters = report.votes_polled,
      turnout_percentage = report.turnout,
      metadata = jsonb_set(
        d.metadata, '{electoral_statistics}',
        jsonb_build_object(
          'status', 'OFFICIAL',
          'source_url', 'https://www.eci.gov.in/eci-backend/public/all_files/full-statistical-reports/telangana/2023/AC_Wise_Voters_Information.pdf',
          'source_title', 'ECI Telangana 2023 Statistical Report, AC Wise Voters Information',
          'sha256', 'f64778fdcdda71cc812169e1c3d447c6f589b61b18be84cf0d1f0e1ffebce95f'
        ), true
      ),
      updated_at = now()
  FROM report
  JOIN public.constituencies c
    ON c.state_code = 'TS' AND c.ac_no = report.ac_no
  WHERE d.state_code = 'TS' AND d.election_year = 2023
    AND d.ac_no = report.ac_no AND d.constituency_id = c.internal_id
    AND (
      d.data_status = 'ESTIMATE'
      OR d.metadata->'electoral_statistics'->>'source_url' = 'https://www.eci.gov.in/eci-backend/public/all_files/full-statistical-reports/telangana/2023/AC_Wise_Voters_Information.pdf'
    );
  GET DIAGNOSTICS row_total = ROW_COUNT;
  IF row_total <> 119 THEN
    RAISE EXCEPTION 'Expected 119 matched Telangana 2023 rows, found %', row_total;
  END IF;
