INSERT INTO public.polling_booths
  (id, internal_id, state_code, constituency_id, constituency_internal_id, booth_number,
   booth_name, polling_station_name, polling_station_address, primary_dataset_version_id, data_status)
SELECT c.id || '-B' || lpad(b.booth_number::text, 3, '0'), gen_random_uuid(),
       c.state_code, c.id, c.internal_id, b.booth_number,
       b.venue, b.venue, b.locality, b.version_id, 'OFFICIAL'
FROM published_booths b
JOIN public.constituencies c ON c.state_code = 'TS' AND c.ac_no = b.ac_no
ON CONFLICT (constituency_id, booth_number) DO NOTHING;

DO $booths$
BEGIN
  IF (
    SELECT count(*) FROM public.polling_booths
    WHERE constituency_id = 'TS-AC-47'
      AND primary_dataset_version_id = 'eci_polling_stations_ts_ac_47_20231004'
      AND data_status = 'OFFICIAL'
  ) <> 407 OR (
    SELECT count(*) FROM public.polling_booths
    WHERE constituency_id = 'TS-AC-93'
      AND primary_dataset_version_id = 'eci_polling_stations_ts_ac_93_20231126'
      AND data_status = 'OFFICIAL'
  ) <> 307 THEN
    RAISE EXCEPTION 'A Telangana polling list did not match its published number of stations';
  END IF;
END $booths$;

COMMIT;
